// Verify the HMAC-SHA256 signature the website sends in X-Signature.
// The secret MUST equal LEAD_FORWARD_SECRET set on the web server.
// Set it in n8n → Credentials/Variables, or paste it below (less safe).
const crypto = require('crypto');
const SECRET = $env.LEAD_FORWARD_SECRET || 'PASTE_LEAD_FORWARD_SECRET_HERE';

const item = $input.first();
// rawBody is the exact bytes the site signed — never re-stringify the parsed JSON.
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : (item.json.rawBody || JSON.stringify(item.json.body));
const headers = item.json.headers || {};
const sig = headers['x-signature'] || headers['X-Signature'] || '';

const expected = crypto.createHmac('sha256', SECRET).update(raw).digest('hex');
const a = Buffer.from(sig);
const b = Buffer.from(expected);
const ok = a.length === b.length && crypto.timingSafeEqual(a, b);

if (!ok) {
  // 401 — reject forged/replayed posts.
  throw new Error('Invalid X-Signature');
}

const lead = JSON.parse(raw);
return [{ json: lead }];

// Map the website lead payload → your ERP/CRM contact + opportunity shape.
// Adjust field names to match your ERP API. This is the ONLY node you must
// customise; everything above is fixed by the website contract.
const d = $json;

const temp = d.temperature || 'cold';
const stage = temp === 'hot' ? 'qualified' : temp === 'warm' ? 'new' : 'lead';

return [{
  json: {
    // — Contact —
    contact: {
      name: d.name || d.company || d.email,
      email: d.email,
      phone: d.phone || null,
      company: d.company || null,
      tags: ['website', d.segment, d.source].filter(Boolean)
    },
    // — Opportunity / deal —
    opportunity: {
      title: `${d.company || d.name || 'Web lead'} — ${d.segment || 'general'}`,
      stage,
      score: d.score ?? 0,
      temperature: temp,
      source: d.source || 'website',
      sourcePage: d.sourcePath || null,
      campaign: d.utm && d.utm.campaign ? d.utm.campaign : null,
      note: d.message || null,
      webLeadId: d.leadId ?? null,
      capturedAt: d.ts || null
    },
    // — Follow-up task (hot leads = same-day) —
    task: {
      title: `Follow up: ${d.company || d.name || d.email}`,
      priority: temp === 'hot' ? 'high' : 'normal',
      dueInHours: temp === 'hot' ? 4 : 24
    }
  }
}];
